CITY_STATE = {
    'Bengaluru':'Karnataka','Noida':'Uttar Pradesh','Gurugram':'Haryana','Mumbai':'Maharashtra','Pune':'Maharashtra','Hyderabad':'Telangana','Chennai':'Tamil Nadu','Ahmedabad':'Gujarat','Jaipur':'Rajasthan','Kolkata':'West Bengal','Delhi':'Delhi','New Delhi':'Delhi','Lucknow':'Uttar Pradesh','Remote':'India'
}

def normalize_existing_job_locations():
    """Make legacy seeded/demo jobs searchable with the same City, State, India format."""
    for job in Job.query.all():
        loc=(job.location or '').strip()
        if not loc: continue
        if 'india' in loc.lower(): continue
        city=loc.split(',')[0].strip()
        state=CITY_STATE.get(city)
        if state:
            job.location=f'{city}, {state}, India'
        else:
            job.location=f'{loc}, India'

def seed():
    # Demo seeding is explicit and is never part of the production deploy path.
    if os.getenv('CAREERHUB_ENV', '').lower() == 'production' and os.getenv('ALLOW_PRODUCTION_SEED', '').lower() not in {'1', 'true', 'yes'}:
        raise SystemExit(
            'Production demo seeding is disabled by default. '
            'Run migrations first, then explicitly set ALLOW_PRODUCTION_SEED=1 '
            'for the one-time demo-data import.'
        )

    app=create_app()
    with app.app_context():
        # Schema creation belongs to Alembic. This seed only inserts missing
        # demo records and never drops, truncates, or clears existing records.
        normalize_existing_job_locations()
        skills={s:Skill.query.filter_by(name=s).first() or Skill(name=s) for s in SKILLS}
        for s in skills.values(): db.session.add(s)
        companies={}
        for name,slug,industry,loc,desc in COMPANIES:
            c=Company.query.filter_by(slug=slug).first() or Company(name=name,slug=slug,industry=industry,location=loc,description=desc,employee_count=100,approval_status='approved')
            db.session.add(c); companies[name]=c
        db.session.flush()
        company_list=list(companies.values())
        for i,row in enumerate(JOBS):
            title,loc,jtype,mode,emin,emax,smin,smax,skillnames=row; slug=f'{title.lower().replace(" ","-")}-{i+1}'
            if Job.query.filter_by(slug=slug).first(): continue
            c=company_list[i%len(company_list)]
            j=Job(company_id=c.id,title=title,slug=slug,description=f'Join {c.name} as a {title}. Work on production systems and collaborate with a cross-functional engineering team.',responsibilities='Build features, review code, troubleshoot issues, document solutions, and collaborate with teammates.',requirements=f'{emin}+ years relevant experience; strong communication; problem solving; practical project experience.',education='Diploma / Bachelor degree in Computer Science, IT, or related field',benefits='Learning budget, flexible work options, paid leave, performance growth opportunities',location=loc,work_mode=mode,job_type=jtype,experience_min=emin,experience_max=emax,salary_min=smin,salary_max=smax,industry=c.industry,status='Active',deadline=datetime.utcnow()+timedelta(days=45-i%20),created_at=datetime.utcnow()-timedelta(days=i%35))
            j.skills=[skills[x] for x in skillnames]; db.session.add(j)
        for email,role,pw in [('candidate@example.com','candidate','Candidate@123'),('recruiter@example.com','recruiter','Recruiter@123')]:
            u=User.query.filter_by(email=email).first()
            if not u:
                u=User(email=email,role=role); u.set_password(pw); db.session.add(u); db.session.flush()
                if role=='candidate': db.session.add(JobSeekerProfile(user_id=u.id,full_name='Demo Candidate',headline='Junior Software Developer',location='Delhi'))
                else: db.session.add(RecruiterProfile(user_id=u.id,full_name='Demo Recruiter',designation='Talent Acquisition',company_id=company_list[0].id))
        db.session.commit()
        cand=User.query.filter_by(email='candidate@example.com').first(); first=Job.query.order_by(Job.id).first()
        if cand and first and not SavedJob.query.filter_by(user_id=cand.id,job_id=first.id).first(): db.session.add(SavedJob(user_id=cand.id,job_id=first.id))
        if cand and first and not Application.query.filter_by(candidate_id=cand.id,job_id=first.id).first():
            db.session.add(Application(candidate_id=cand.id,job_id=first.id,status='Applied',cover_letter='I am interested in this opportunity and would love to contribute.',additional_info='Demo application created by seed data.'))
        if cand and not Notification.query.filter_by(user_id=cand.id,title='Welcome to CareerHub').first():
            db.session.add(Notification(user_id=cand.id,title='Welcome to CareerHub',message='Your demo candidate account is ready. Complete your profile and start applying.',link='/candidate/profile'))
        recruiter=User.query.filter_by(email='recruiter@example.com').first()
        if cand and recruiter and not Message.query.filter_by(sender_id=recruiter.id,receiver_id=cand.id).first():
            db.session.add(Message(sender_id=recruiter.id,receiver_id=cand.id,subject='Welcome to CareerHub',body='Thanks for exploring CareerHub. Complete your profile and apply to roles that match your skills.'))
        db.session.commit(); print(f'Seed complete: {Company.query.count()} companies, {Job.query.count()} jobs, {Skill.query.count()} skills, {Application.query.count()} applications.')
if __name__=='__main__': seed()
